package com.controlbridge.mobile.ui

import android.graphics.*
import android.view.*
import android.content.Context
import android.os.SystemClock
import kotlin.math.min

class DashboardView(context:Context):View(context){
    enum class Page{HOME,HUD,SETTINGS};var page=Page.HOME;var tv=false;var controller=false;var ip="127.0.0.1";var message="Ponte pronta";var onAction:(String)->Unit={};private val p=Paint(1);private var hover="";private var press="";private var anim=0f;private var isShown=true
    init{isFocusable=true;setBackgroundColor(Color.rgb(5,7,12))}
    override fun onDraw(c:Canvas){super.onDraw(c);anim=((SystemClock.uptimeMillis()%6000)/6000f);val w=width.toFloat();val h=height.toFloat();val u=min(w,h);p.shader=LinearGradient(0f,0f,w,h,Color.rgb(5,7,12),Color.rgb(14,18,29),Shader.TileMode.CLAMP);c.drawRect(0f,0f,w,h,p);p.shader=null;p.color=Color.argb(18,90,125,255);c.drawCircle(w*(.18f+anim*.64f),h*.35f,u*.36f,p);p.color=Color.argb(10,130,90,255);c.drawCircle(w*(.75f-anim*.35f),h*.75f,u*.28f,p);header(c,w);when(page){Page.HOME->home(c,w,h);Page.HUD->hud(c,w,h);Page.SETTINGS->settings(c,w,h)};if(isShown)postInvalidateDelayed(16)}
    private fun header(c:Canvas,w:Float){p.color=Color.argb(165,12,16,26);c.drawRoundRect(24f,20f,w-24f,78f,28f,28f,p);text(c,"CONTROLBRIDGE",48f,47f,15f,Color.WHITE,true);text(c,"REMOTE GAMEPAD • LOCAL BRIDGE",48f,65f,8f,Color.rgb(125,140,166),false);dot(c,w-190f,49f,tv,"TV");dot(c,w-112f,49f,controller,"CTRL")}
    private fun dot(c:Canvas,x:Float,y:Float,on:Boolean,label:String){p.color=if(on)Color.rgb(86,222,159)else Color.rgb(95,105,125);c.drawCircle(x,y,4f,p);text(c,label,x+10,y+3,8f,Color.rgb(185,195,214),false)}
    private fun home(c:Canvas,w:Float,h:Float){text(c,"Sua central de controle",48f,130f,28f,Color.WHITE,true);text(c,"O celular vira a ponte entre seu controle e a TV.",48f,154f,11f,Color.rgb(153,165,190),false);button(c,w-220f,94f,w-48f,140f,"CONECTAR TV","connect");card(c,48f,190f,w*.47f,h-34f,"CONTROLE FÍSICO",if(controller)"Conectado" else "Aguardando controle",controller);card(c,w*.53f,190f,w-48f,h-34f,"REDE LOCAL",if(tv)"TV conectada" else "Pronta para parear",tv);button(c,48f,h-92f,210f,h-38f,"INICIAR PONTE","start");button(c,224f,h-92f,386f,h-38f,"PAINEL DE CONTROLE","hud");button(c,400f,h-92f,562f,h-38f,"CONFIGURAÇÕES","settings");text(c,"IP local  $ip",w-230f,h-58f,9f,Color.rgb(120,135,160),false)}
    private fun card(c:Canvas,l:Float,t:Float,r:Float,b:Float,title:String,value:String,on:Boolean){p.color=Color.argb(145,12,17,28);c.drawRoundRect(l,t,r,b,24f,24f,p);p.style=Paint.Style.STROKE;p.strokeWidth=1f;p.color=Color.argb(if(on)100 else 35,110,140,210);c.drawRoundRect(l,t,r,b,24f,24f,p);p.style=Paint.Style.FILL;text(c,title,l+20,t+28,9f,Color.rgb(110,128,157),true);text(c,value,l+20,t+70,22f,if(on)Color.rgb(95,226,163)else Color.WHITE,true);text(c,if(on)"● SINCRONIZADO" else "○ DISPONÍVEL",l+20,b-22,9f,if(on)Color.rgb(95,226,163)else Color.rgb(145,155,177),false)}
    private fun hud(c:Canvas,w:Float,h:Float){text(c,"Ponte ativa",48f,126f,26f,Color.WHITE,true);text(c,"Entrada física é encaminhada em tempo real.",48f,149f,10f,Color.rgb(150,164,188),false);panel(c,48f,180f,w-48f,h-52f);text(c,"L",w*.27f,h*.57f,16f,Color.rgb(120,140,180),true);text(c,"R",w*.73f,h*.57f,16f,Color.rgb(120,140,180),true);text(c,"D-PAD",w*.12f,h*.78f,9f,Color.rgb(110,125,150),true);text(c,"A   B   X   Y",w*.80f,h*.78f,10f,Color.rgb(110,125,150),true);button(c,w-196f,100f,w-48f,148f,"VOLTAR","home")}
    private fun panel(c:Canvas,l:Float,t:Float,r:Float,b:Float){p.color=Color.argb(125,9,13,22);c.drawRoundRect(l,t,r,b,30f,30f,p);p.style=Paint.Style.STROKE;p.strokeWidth=1f;p.color=Color.argb(55,105,135,200);c.drawRoundRect(l,t,r,b,30f,30f,p);p.style=Paint.Style.FILL;for(i in 0..5){p.color=Color.argb(12,100,130,190);c.drawLine(l+20,t+65+i*42,r-20,t+65+i*42,p)}}
    private fun settings(c:Canvas,w:Float,h:Float){text(c,"Configurações",48f,130f,28f,Color.WHITE,true);text(c,"Personalize a ponte sem tocar no motor de entrada.",48f,154f,10f,Color.rgb(150,164,188),false);setting(c,48f,190f,w-48f,248f,"Tema","Midnight Glass");setting(c,48f,264f,w-48f,322f,"Áudio da interface","Foco • clique • abrir/fechar");setting(c,48f,338f,w-48f,396f,"Transporte","WebSocket + Bluetooth HID");button(c,48f,h-92f,196f,h-38f,"VOLTAR","home")}
    private fun setting(c:Canvas,l:Float,t:Float,r:Float,b:Float,a:String,v:String){p.color=Color.argb(120,13,18,29);c.drawRoundRect(l,t,r,b,20f,20f,p);text(c,a,l+20,t+23,10f,Color.rgb(125,140,165),true);text(c,v,l+20,t+46,11f,Color.WHITE,false)}
    private fun button(c:Canvas,l:Float,t:Float,r:Float,b:Float,label:String,id:String){val active=id==press||id==hover;p.color=Color.argb(if(active)42 else 18,100,130,255);c.drawRoundRect(l,t,r,b,18f,18f,p);p.style=Paint.Style.STROKE;p.strokeWidth=1f;p.color=Color.argb(if(active)110 else 30,110,140,210);c.drawRoundRect(l,t,r,b,18f,18f,p);p.style=Paint.Style.FILL;text(c,label,(l+r)/2,t+33,9f,Color.rgb(218,225,239),true,Paint.Align.CENTER)}
    private fun text(c:Canvas,s:String,x:Float,y:Float,size:Float,color:Int,bold:Boolean=false,align:Paint.Align=Paint.Align.LEFT){p.shader=null;p.style=Paint.Style.FILL;p.color=color;p.textSize=size;p.typeface=if(bold)Typeface.DEFAULT_BOLD else Typeface.DEFAULT;p.textAlign=align;c.drawText(s,x,y,p);p.textAlign=Paint.Align.LEFT}
    override fun onTouchEvent(e:MotionEvent):Boolean{val id=hit(e.x,e.y);when(e.action){MotionEvent.ACTION_DOWN->{press=id;invalidate();return true};MotionEvent.ACTION_UP->{if(id==press&&id.isNotEmpty())onAction(id);press="";invalidate();return true};MotionEvent.ACTION_HOVER_MOVE->{hover=id;invalidate()}};return true}
    private fun hit(x:Float,y:Float):String{val h=height.toFloat();return when{page==Page.HOME&&x>width-235&&y in 88f..150f->"connect";page==Page.HOME&&y>h-110&&x in 48f..210f->"start";page==Page.HOME&&y>h-110&&x in 224f..386f->"hud";page==Page.HOME&&y>h-110&&x in 400f..562f->"settings";page==Page.HUD&&x>width-210&&y in 90f..165f->"home";page==Page.SETTINGS&&y>height-110&&x<230->"home";else->""}}
}
